-- Modernizing dbt wiki section (top-level sibling of "Data modeling").
-- A focused practitioner playbook for cleaning up / modernizing a sprawling dbt
-- project. Idempotent: pages upsert by slug; parent wiring and wikilinks are
-- join-based and safe to re-run. Cross-links target existing pages in
-- Transformation and orchestration / Analytics engineering / ops, so a single
-- pass resolves everything. Seeded to the live DB via the Supabase MCP (2026-06).

insert into pages (title, slug, kind, content, visibility) values ('Modernizing dbt', 'modernizing-dbt', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Most dbt projects don't start a mess. They become one. Enough analysts answer enough questions by building a new model off whatever was nearest, and a few years later you have thousands of models, no canonical core, the same metric defined five slightly-different ways, and a DAG nobody fully understands. This section is the playbook for fixing that."}]},{"type":"paragraph","content":[{"type":"text","text":"It's the at-scale, hands-on companion to "},{"type":"wikilink","attrs":{"title":"Transformation and orchestration"}},{"type":"text","text":", which covers dbt from the start. Here the assumption is that the project already exists and already hurts, and the work is to assess it, plan a cleanup, execute it without breaking the people who depend on it, and govern it so the sprawl doesn't grow back."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The arc"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"See it — ","marks":[{"type":"bold"}]},{"type":"text","text":"what sprawl looks like and the anti-patterns that produce it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Assess it — ","marks":[{"type":"bold"}]},{"type":"text","text":"audit the project objectively before touching anything."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fix it — ","marks":[{"type":"bold"}]},{"type":"text","text":"design a canonical core, plan the sequence, execute the refactor safely."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep it clean — ","marks":[{"type":"bold"}]},{"type":"text","text":"materialization and metrics-layer discipline, CI governance, mesh, cost, and ownership."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The hardest part is not the SQL. It's doing this without breaking production and without it growing straight back, which is a governance and ownership problem as much as a modeling one. Honest caveat throughout: many of the cost and tool figures here are 2026 vendor numbers, flagged as such."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"dbt sprawl and the missing core"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Planning a dbt modernization"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Modernizing dbt voices and canon"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('dbt sprawl and the missing core', 'dbt-sprawl-and-the-missing-core', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"\"Sprawl\" is a DAG that grew by accretion. Without an enforced layering, naming, and a central conformed layer that owns the canonical entities, every new question becomes a new model hung off whatever was closest, and the same few problems repeat across the graph."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"What it looks like"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"No canonical core — ","marks":[{"type":"bold"}]},{"type":"text","text":"there's no agreed set of conformed dimensions and facts, so \"active customer\" and \"net revenue\" get recomputed, slightly differently, in five marts. The numbers don't reconcile and nobody can say which is right."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"God models — ","marks":[{"type":"bold"}]},{"type":"text","text":"one model joins a dozen sources and encodes a dozen rules. It's the thing everyone is afraid to touch."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"View-on-view chains — ","marks":[{"type":"bold"}]},{"type":"text","text":"views stacked on views, so every downstream read re-executes the entire ancestry."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marts reaching to raw — ","marks":[{"type":"bold"}]},{"type":"text","text":"models that skip staging and read source tables directly, so cleaning logic lives inconsistently in many places."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Orphaned models — ","marks":[{"type":"bold"}]},{"type":"text","text":"models that still run and cost compute every day, but nothing queries."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"How it happens is always the same: no enforced "},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":" discipline, no canonical core, no CI gate on any of it, and decentralized authorship with no ownership. The good news is that each smell has a name and a fix, catalogued in "},{"type":"wikilink","attrs":{"title":"dbt anti-patterns"}},{"type":"text","text":", and the mess can be measured before you touch it, which is "},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"dbt anti-patterns"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Designing the canonical core"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('dbt anti-patterns', 'dbt-anti-patterns', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The useful thing about dbt's failure modes is that they're finite and named. Most map directly to a rule in the dbt_project_evaluator package, which means you can detect them mechanically. Each one: the smell, why it hurts, the fix."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Direct join to source — ","marks":[{"type":"bold"}]},{"type":"text","text":"a mart pulls some columns from staging and some straight from raw, so casing and casts happen in two places. Fix: raw data enters through exactly one staging model; everything downstream refs that."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hardcoded references — ","marks":[{"type":"bold"}]},{"type":"text","text":"writing analytics.prod.orders instead of ref() or source(). Breaks the DAG, environment-aware schemas, and lineage. Fix: always ref/source. This is the single most load-bearing convention in dbt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"View-on-view chains — ","marks":[{"type":"bold"}]},{"type":"text","text":"stacked views re-run their whole ancestry on every read. Fix: materialize the expensive or frequently-read layers as tables."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"God marts — ","marks":[{"type":"bold"}]},{"type":"text","text":"one model joining ten-plus entities and every possible aggregation. Fix: keep marts as generalized facts and dims (a handful of entities), compose in intermediate models, let BI combine the rest."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Duplicated business logic — ","marks":[{"type":"bold"}]},{"type":"text","text":"the same metric redefined across marts. Fix: define it once, in an intermediate model or the metrics layer."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Rejoining the grain / fan traps — ","marks":[{"type":"bold"}]},{"type":"text","text":"joining a one-to-many then aggregating without care double-counts. Fix: aggregate at the right grain before joining, or push the shared concept upstream."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT star — ","marks":[{"type":"bold"}]},{"type":"text","text":"schema drift propagates silently and column pruning is defeated. Fix: explicit column lists, especially in staging."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"A 2026 cost note that reframes the priority: audits repeatedly find the top 10% of models drive 65 to 75% of compute (directional). So the highest-value move is usually to fix the few heavy models and delete the dead ones, not to micro-optimize everything. See "},{"type":"wikilink","attrs":{"title":"dbt cost and economics"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"dbt sprawl and the missing core"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Materialization and incremental strategy"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Auditing a dbt project', 'auditing-a-dbt-project', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Quantify how bad it is before you refactor anything. An audit turns \"this feels messy\" into a prioritized list with numbers."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The instruments"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt_project_evaluator — ","marks":[{"type":"bold"}]},{"type":"text","text":"the primary audit tool. It scans the DAG and emits one table per rule (modeling, testing, documentation, structure, performance, governance) listing the offending nodes. Run it as a one-shot, or in CI with an exceptions seed so it gates new debt without forcing a big-bang fix."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Column-level lineage — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt Explorer / Catalog (or SQLMesh) shows which column feeds which downstream, so you can find the god models by fan-in and fan-out and answer \"what breaks if I touch this.\""}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Unused-model detection — ","marks":[{"type":"bold"}]},{"type":"text","text":"the robust method is not \"zero queries equals delete,\" because staging legitimately has zero direct selects. Instead, propagate usage up the DAG: a model is unused only if it and all its descendants have no real (non-dbt) queries in the warehouse query history over the last few months."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Cost attribution — ","marks":[{"type":"bold"}]},{"type":"text","text":"parse the dbt query comment or tag and join to the warehouse's per-query cost view to rank models by spend (dbt-snowflake-monitoring, or dbt Cost Insights). Watch the unattributed fraction; attribution is worthless if a quarter of spend is untagged."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The metrics that define \"how bad\": percent of models violating each evaluator rule, number of god models, max view-chain depth, count of direct-source references in marts, test and primary-key and documentation coverage, number of unused models and their dollars per day, and number of duplicated metric definitions. Those numbers become the prioritization input for "},{"type":"wikilink","attrs":{"title":"Planning a dbt modernization"}},{"type":"text","text":". The tools themselves are in "},{"type":"wikilink","attrs":{"title":"The dbt tooling belt"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The dbt tooling belt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Planning a dbt modernization"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"dbt cost and economics"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Designing the canonical core', 'designing-the-canonical-core', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The thing a sprawling project is missing is a canonical core: the small set of conformed dimensions and facts the business actually agrees on, built once, that everything else references. Designing it is the center of the modernization, because it's what lets you delete the duplicates."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The target shape"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Staging — ","marks":[{"type":"bold"}]},{"type":"text","text":"one model per source table, the only layer that refs sources, light renaming and casting only, materialized as views."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Intermediate — ","marks":[{"type":"bold"}]},{"type":"text","text":"where duplicated logic gets conformed into shared building blocks, each with a single clear purpose."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Marts (the core) — ","marks":[{"type":"bold"}]},{"type":"text","text":"the conformed facts and dimensions that are the single source of truth, referenced by everything downstream, materialized as tables."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The governing principle is to apply each transformation in exactly one place. That one rule is the antidote to copy-paste and divergent metrics. Building the core means picking the handful of entities the business agrees on (customer, order, subscription), modeling them once, and then re-pointing everything else at them."}]},{"type":"paragraph","content":[{"type":"text","text":"This is the same dimensional thinking as "},{"type":"wikilink","attrs":{"title":"Modeling theory"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Modeling approaches in dbt"}},{"type":"text","text":", applied as a remediation rather than a greenfield design, and it leans entirely on getting the "},{"type":"wikilink","attrs":{"title":"Grain"}},{"type":"text","text":" of each conformed model right. The metric definitions that used to be scattered become candidates for "},{"type":"wikilink","attrs":{"title":"The metrics layer (MetricFlow)"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"How to structure a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Modeling approaches in dbt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Grain"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Planning a dbt modernization', 'planning-a-dbt-modernization', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With an audit in hand, the plan is about scope, sequence, and not betting the company on a big-bang rewrite."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Strangler-fig, not big-bang"}]},{"type":"paragraph","content":[{"type":"text","text":"Build the new conformed models alongside the old ones and route consumers over gradually, then decommission the legacy once nothing reads it. This is the consensus modernization pattern for exactly this risk profile, and dbt's own refactoring guidance endorses the \"alongside\" strategy precisely because it lets you prove old equals new before switching. Each conformed model ships independently and delivers value early, so risk and blast radius stay small."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Sequencing and prioritization"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"By lineage layer — ","marks":[{"type":"bold"}]},{"type":"text","text":"sources and staging first, then intermediate, then marts, so each layer is locked before the next moves."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"By value and risk — ","marks":[{"type":"bold"}]},{"type":"text","text":"start with the most-duplicated, highest-value canonical entities; prune clearly-dead models early for a fast cost win; defer the low-traffic long tail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Deprecation strategy — ","marks":[{"type":"bold"}]},{"type":"text","text":"use deprecation_date (which warns as the date approaches and blocks deletion of contracted models before it), model versions so old and new coexist during the window, and aliases or shims so BI tools don't break."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"One hard-won rule from teams who've done large moves: don't refactor and migrate at the same time. Optimizing while relocating steals focus and multiplies risk; make the cleanup a deliberate, separate phase. The execution mechanics are in "},{"type":"wikilink","attrs":{"title":"Executing a refactor safely"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Executing a refactor safely"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Designing the canonical core"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Executing a refactor safely', 'executing-a-refactor-safely', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The core safety move is parallel-run plus diff: build the refactored model next to the legacy one and prove they produce the same output before cutover."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Proving parity"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"audit_helper — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dbt package for old-versus-new diffing. compare_relations hashes all rows in two relations for a fast \"row-identical\" check; compare_queries does row-by-row comparison and lets you filter, rename, and recast to line two queries up. The standard tool when moving a legacy model into dbt."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"data-diff — ","marks":[{"type":"bold"}]},{"type":"text","text":"value-level and statistical diffing across prod and a branch, surfaced as downstream impact on every PR. It catches the regressions tests miss (\"it compiles, tests pass, but three percent of revenue moved\"). Note the open-source data-diff has been unmaintained since 2024; audit_helper is the durable open-source choice."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Keeping CI cheap during the migration"}]},{"type":"paragraph","content":[{"type":"text","text":"Slim CI with state:modified+ and deferral builds only changed models and pulls unchanged parents from prod, so a long migration doesn't rebuild the world on every PR. Clone incremental models as the first CI step so they run incrementally instead of forcing expensive full refreshes. Then phase the rollout: stand up the new models, point a canary set of consumers at them, soak, and widen."}]},{"type":"paragraph","content":[{"type":"text","text":"Definition of done per phase: the new model passes its contract and tests, audit_helper or data-diff shows old equals new (or the difference is explained and approved), every downstream consumer including exposures is re-pointed, the legacy model is marked deprecated with a date, and after the soak it and its warehouse table are dropped. This is "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}},{"type":"text","text":" pointed at a migration."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Planning a dbt modernization"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"The dbt tooling belt"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"CI/CD and DataOps"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Materialization and incremental strategy', 'materialization-and-incremental-strategy', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Materialization is the highest-leverage cost decision in a dbt project, and at scale it's where modernization pays for itself. The golden rule, straight from dbt: start as a view, make it a table when it's slow to query, make it incremental when the table is slow to build. The conceptual menu is in "},{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":"; this page is the at-scale detail."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Incremental, where the money is"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"merge — ","marks":[{"type":"bold"}]},{"type":"text","text":"upsert by unique_key, the default. The cost trap: without incremental_predicates, MERGE scans the entire destination to find matches, so inserting a thousand rows into a half-billion-row table still scans half a billion rows. Bound the scan with a predicate (for example, only the last seven days), and never let unique_key be null or it silently duplicates."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"insert_overwrite — ","marks":[{"type":"bold"}]},{"type":"text","text":"replace whole partitions, ideal on partitioned warehouses like BigQuery; avoids row-by-row key matching."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"microbatch — ","marks":[{"type":"bold"}]},{"type":"text","text":"splits a time range into atomic batches by an event_time column. No hand-written is_incremental filter, idempotent batches, retry only reruns failed batches, and backfills run without a full refresh."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Full-refresh discipline"}]},{"type":"paragraph","content":[{"type":"text","text":"The dominant cost in many projects is not steady-state incremental runs, it's an accidental or scheduled full refresh of a huge model. Set full_refresh: false on big incrementals so a stray flag can't rebuild a billion rows, and use on_schema_change (append_new_columns or sync_all_columns) so new source columns don't silently drop. Match the choice to each model, not the whole project. This is "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}},{"type":"text","text":" at the model level."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Materialization strategies"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"dbt cost and economics"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The metrics layer (MetricFlow)', 'the-metrics-layer-metricflow', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The durable fix for duplicated metric logic is to define each metric once, in code, in the dbt Semantic Layer. MetricFlow is the engine: it builds a semantic graph and generates joins at query time, so \"revenue\" and \"active users\" can't drift across marts and BI tools. This is the dbt-specific, hands-on view of "},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":"."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The building blocks"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Semantic model — ","marks":[{"type":"bold"}]},{"type":"text","text":"one per dbt model, declaring its entities, dimensions, and measures."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Entities — ","marks":[{"type":"bold"}]},{"type":"text","text":"the join keys (primary, foreign, unique); MetricFlow uses them to pick join paths and claims to avoid fan-out and chasm joins."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Dimensions and measures — ","marks":[{"type":"bold"}]},{"type":"text","text":"dimensions are categorical or time; measures are a column plus an aggregation, and they're the building blocks of metrics."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Metric types — ","marks":[{"type":"bold"}]},{"type":"text","text":"simple (one measure), ratio (numerator over denominator), cumulative (a running window), and derived (an expression over other metrics)."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"It doesn't replace marts. You still build clean facts and dims; the semantic models sit on top and compute aggregations and joins dynamically, so you stop pre-baking every aggregation into wide tables and stop copying metric logic. Consumption is through JDBC, GraphQL, and BI integrations, so one definition flows everywhere, including to AI agents (the point of "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}},{"type":"text","text":"). Gotchas as of 2026: MetricFlow was open-sourced under Apache 2.0 in late 2025 but the served layer and APIs are still largely a dbt Cloud product, the YAML has a real learning curve, and minor versions have shipped breaking changes, so pin them."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"The semantic layer"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Designing the canonical core"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Serving data to AI agents"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Preventing re-sprawl', 'preventing-re-sprawl', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A refactor without governance just regrows the sprawl. The fix is to make the conventions automatic, enforced in CI and pre-commit so the anti-patterns can't reaccumulate."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt_project_evaluator in CI — ","marks":[{"type":"bold"}]},{"type":"text","text":"fail the build on new modeling, testing, or documentation violations. Use the exceptions seed as a ratchet: grandfather the existing debt, block anything new, and chip away at the exceptions over time."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt-checkpoint — ","marks":[{"type":"bold"}]},{"type":"text","text":"pre-commit hooks that enforce metadata before code lands: every model has a description, tests, an owner in meta, and uses ref/source instead of hardcoded table names."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SQLFluff — ","marks":[{"type":"bold"}]},{"type":"text","text":"a SQL linter and auto-fixer run on changed files, so style and structure stay consistent without a reviewer policing it."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Contracts, versions, access — ","marks":[{"type":"bold"}]},{"type":"text","text":"model contracts enforce output shape at build time; versions let public models evolve safely; access modifiers keep internal models from quietly becoming someone's load-bearing dependency."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"The deeper point is that governance has to be infrastructure, not an afterthought, exactly the lesson from "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}},{"type":"text","text":". A convention that isn't enforced in CI is a suggestion, and suggestions are how you got the sprawl. When ownership boundaries are real, the next step up is splitting the monolith, which is "},{"type":"wikilink","attrs":{"title":"dbt Mesh and decomposition"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"dbt Mesh and decomposition"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Testing & data quality"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Principles of analytics engineering"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('dbt Mesh and decomposition', 'dbt-mesh-and-decomposition', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Mesh breaks a monolith into multiple independently-owned projects that share data products through cross-project ref(), resolved by a metadata service rather than by importing one project into another. The governance primitives are model groups (ownership), access (public, protected, private), contracts (enforced shape), and versions (safe evolution)."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"When it helps, and when it hurts"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Helps at scale — ","marks":[{"type":"bold"}]},{"type":"text","text":"dozens of teams, or a central platform team bottlenecking many downstream teams (hub-and-spoke). Mesh lets the spokes move independently while the hub guards the core."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hurts when small — ","marks":[{"type":"bold"}]},{"type":"text","text":"for a single team under about five people, the overhead of managing multiple projects outweighs the benefit. Mesh deliberately adds friction to prevent accidental cross-team changes; that friction only pays off when the ownership boundaries are real."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"So don't split a project just because it's big. Split it when teams genuinely own different domains, and then make that ownership enforceable. Treat every public model as a product API: contracts mandatory, versioned, documented, and never depended on by an exposure through a private model. Note cross-project refs are a dbt Enterprise feature, while access, contracts, and versions work in dbt Core. The org question underneath this is "},{"type":"wikilink","attrs":{"title":"Who owns the dbt project"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Preventing re-sprawl"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Who owns the dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data contracts and trust"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('dbt cost and economics', 'dbt-cost-and-economics', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"At scale, dbt is a major line on the warehouse bill, and modernization is partly a cost exercise. The first move is attribution: parse the dbt query tag and join it to the warehouse's per-query cost view, so you know which models cost what."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Where the money actually goes"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"The heavy few — ","marks":[{"type":"bold"}]},{"type":"text","text":"the top ten percent of models typically drive most of the spend (one 2026 audit: forty models out of four hundred were seventy-two percent of the bill). Optimize those, prune the dead ones, and ignore the long tail."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Full refreshes — ","marks":[{"type":"bold"}]},{"type":"text","text":"your full-refresh is the bill. An accidental or scheduled full rebuild of a huge incremental is where credits vanish; see the discipline in "}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"CI rebuilds — ","marks":[{"type":"bold"}]},{"type":"text","text":"physically rebuilding tables on every pull request adds up; mitigate with slim CI, deferral, and cloning before reaching for a different engine."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The 2026 levers (vendor figures, flagged)"}]},{"type":"paragraph","content":[{"type":"text","text":"dbt's state-aware approach (the Fusion engine, now folded into \"dbt State\") rebuilds only models whose code or upstream data actually changed, with dbt Labs claiming roughly 30% compute reduction. SQLMesh's virtual data environments make dev and CME environments logical pointers rather than physical copies, with Tobiko claiming order-of-magnitude savings. Both numbers are vendor-reported and unverified independently, and the comparison is a moving target as dbt closes the gap. Treat them as directional. This is "},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}},{"type":"text","text":" applied to the transformation layer."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Materialization and incremental strategy"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Cost as a data product"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"FinOps and cloud cost"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('The dbt tooling belt', 'the-dbt-tooling-belt', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A modernization has four jobs, and a tool for each: find what's wrong, prove a rewrite didn't change the numbers, keep new work clean, and see cost and runtime."}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Find what's wrong — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt_project_evaluator (DAG-level best-practice rules), dbt Explorer / Catalog (column-level lineage), and query-history analysis for unused models."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Prove parity — ","marks":[{"type":"bold"}]},{"type":"text","text":"audit_helper (compare_relations, compare_queries) for hand-driven old-versus-new proofs, and Datafold data-diff for automated downstream diffs in CI. codegen generates boilerplate so onboarding legacy tables is mechanical."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Keep it clean — ","marks":[{"type":"bold"}]},{"type":"text","text":"SQLFluff (SQL linting) and dbt-checkpoint (pre-commit metadata hooks), wired into CI."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"See cost and runtime — ","marks":[{"type":"bold"}]},{"type":"text","text":"dbt_artifacts or Elementary load run results, timings, and freshness into the warehouse so you can rank slow models and alert on anomalies."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Serve it to agents — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dbt MCP server exposes models, metrics, docs, lineage, and tests as tools an AI agent can call, so an agent reasons over real context instead of guessing."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"One honest flag: the open-source data-diff has been unmaintained since 2024, so for a living dependency prefer audit_helper (open-source) or the commercial Datafold Cloud. None of these tools fix the project for you; they make the mess visible and keep the fix from regressing. They feed both "},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Preventing re-sprawl"}},{"type":"text","text":"."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Auditing a dbt project"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Preventing re-sprawl"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Data observability"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Who owns the dbt project', 'who-owns-the-dbt-project', 'concept', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The deepest cause of sprawl is organizational: the central marts everyone references but no team is accountable for. \"No one owns the central model\" is how the core rots into undocumented, untested, contradictory grain, and it's why a cleanup that ignores ownership grows straight back."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The two failure modes, and the fix"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fully centralized — ","marks":[{"type":"bold"}]},{"type":"text","text":"one platform team owns everything and becomes the bottleneck; every change queues behind them."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Fully embedded — ","marks":[{"type":"bold"}]},{"type":"text","text":"analysts inside each team move fast but produce duplicated, incoherent core models."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Hub-and-spoke — ","marks":[{"type":"bold"}]},{"type":"text","text":"the consensus answer. The hub is an enablement team that provides guardrails, CI checks, shared macros, and governs the public interfaces, explicitly not fixing everyone's models. The spokes (domain teams) own their content."}]}]}]},{"type":"paragraph","content":[{"type":"text","text":"Make ownership concrete: every public or core model gets a named owning team (model groups plus an owner in meta), with contracts and versions as its API. That's also the boundary that justifies a "},{"type":"wikilink","attrs":{"title":"dbt Mesh and decomposition"}},{"type":"text","text":" split. This is the same hub-and-spoke argument as "},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}},{"type":"text","text":" and "},{"type":"wikilink","attrs":{"title":"Team and ownership models"}},{"type":"text","text":", here pointed squarely at the dbt project: the structure follows the ownership, and the semantic layer is what lets the spokes share numbers."}]},{"type":"paragraph","content":[{"type":"text","text":"Related: ","marks":[{"type":"bold"}]},{"type":"wikilink","attrs":{"title":"Org models (hub and spoke)"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"dbt Mesh and decomposition"}},{"type":"text","text":" · "},{"type":"wikilink","attrs":{"title":"Team and ownership models"}}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
insert into pages (title, slug, kind, content, visibility) values ('Modernizing dbt voices and canon', 'modernizing-dbt-voices', 'wiki', $j${"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt-at-scale has an active, practical canon, much of it vendor engineering blogs and conference talks. Who to read and why, weighted to 2026."}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The primary source"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"dbt Labs — ","marks":[{"type":"bold"}]},{"type":"text","text":"the Developer Hub and blog: the \"How we structure\" and \"How we mesh\" guides, \"Refactoring legacy SQL to dbt,\" the dbt_project_evaluator intro, and the Fusion / state-aware / dbt State announcements."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"The practitioners"}]},{"type":"bulletList","content":[{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datacoves — ","marks":[{"type":"bold"}]},{"type":"text","text":"vendor-neutral CI/CD, slim-CI, and governance content."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Datafold — ","marks":[{"type":"bold"}]},{"type":"text","text":"the regression-testing and data-diff canon (audit_helper versus data-diff, development testing)."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Tobiko Data — ","marks":[{"type":"bold"}]},{"type":"text","text":"SQLMesh: virtual environments and the dbt-versus-SQLMesh cost benchmarks, read as vendor numbers."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"SELECT and Elementary — ","marks":[{"type":"bold"}]},{"type":"text","text":"Snowflake-dbt cost optimization and dbt-native observability."}]}]},{"type":"listItem","content":[{"type":"paragraph","content":[{"type":"text","text":"Brooklyn Data and Indicium — ","marks":[{"type":"bold"}]},{"type":"text","text":"the dbt_artifacts package and large-scale migration write-ups."}]}]}]},{"type":"heading","attrs":{"level":3},"content":[{"type":"text","text":"Balance the vendors"}]},{"type":"paragraph","content":[{"type":"text","text":"Coalesce talks and the dbt Community are the living record; Hugo Lu (Orchestra) writes the sharpest skeptical counterweight to vendor posts. Read the cost claims as marketing benchmarks until someone independent replicates them."}]},{"type":"paragraph","content":[{"type":"text","text":"Tool, version, and corporate facts here are dated to 2025 and 2026 and move monthly. Confirm before relying on them.","marks":[{"type":"italic"}]}]}]}$j$::jsonb, 'viewer') on conflict (slug) do nothing;
update pages c set parent_id = pa.id from pages pa where pa.slug = 'modernizing-dbt' and c.slug in ('dbt-sprawl-and-the-missing-core','dbt-anti-patterns','auditing-a-dbt-project','designing-the-canonical-core','planning-a-dbt-modernization','executing-a-refactor-safely','materialization-and-incremental-strategy','the-metrics-layer-metricflow','preventing-re-sprawl','dbt-mesh-and-decomposition','dbt-cost-and-economics','the-dbt-tooling-belt','who-owns-the-dbt-project','modernizing-dbt-voices');
